async function e(n){let t=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(n));return[...new Uint8Array(t)].map(r=>r.toString(16).padStart(2,"0")).join("")}function a(n){return String(n||"").trim().toLowerCase().replace(/\s+/g," ")}async function i(n){return(await e("familyhub|"+a(n))).slice(0,40)}async function c(n,t){return e(n+"|pin|"+String(t).trim())}function s(n=20){let t="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";return[...crypto.getRandomValues(new Uint8Array(n))].map(o=>t[o%t.length]).join("")}export{e as a,i as b,c,s as d};
